// 原普通100/102..105及副106；103保留源索引缓存，105移除自身后继续扫描。
#pragma once
#include "core/stages/Stage6BossFinalArithmetic.hpp"
#include "core/stages/Stage6BossFinalEmission.hpp"
namespace kaikeidou {
inline void update_stage6_boss_final_projectile(ProjectilePools& pool,std::uint32_t index,std::uint32_t behavior,const ObjectRecord<240>& player,PatternParameters& p,Random& random,RandomPrecision precision,GameMath& math){
 using namespace stage6_boss_final_detail;const Arithmetic m{{static_cast<unsigned>(precision)}};const auto real=[](std::uint64_t v){return crt_sse2::real(v);};
 if(behavior==106){auto& s=pool.secondary.at(index);const auto q=[&](std::size_t o){return m.q(s.quad(o));};if(!s.word(0x48))stage6_boss_final_approach(s,0x20,s.quad(0x28),constant(0x6d1a40),m.precision);else if(s.word(0x48)==1){const auto dx=m.store(m.sub(m.q(player.quad(0x90)),q(0x10))),dy=m.store(m.sub(m.q(player.quad(0x98)),q(0x18)));const auto angle=m.store(math.atan2(dy,dx));const auto square=m.store(m.add(m.mul(m.q(dx),m.q(dx)),m.mul(m.q(dy),m.q(dy))));const auto distance=m.store(m.mul(stage6_boss_final_sqrt(square,m.precision),m.c(0x6a7708)));const auto cosine=math.cosine(angle);s.quad(0x10,m.store(m.add(m.mul(cosine,m.q(distance)),q(0x10))));const auto sine=math.sine(angle);s.quad(0x18,m.store(m.add(m.mul(sine,m.q(distance)),q(0x18))));stage6_boss_final_approach(s,0x20,pool.secondary[0].quad(0x28),constant(0x6d1a88),m.precision);}else if(s.word(0x48)==0xffffffffu){stage6_boss_final_approach(s,0x20,0,constant(0x6d1a40),m.precision);if(real(s.quad(0x20))<=1.)s.word(0,0);}return;}
 auto b=record(pool,index);const auto q=[&](std::size_t o){return m.q(b.quad(o));};const auto put=[&](std::size_t o,binary_float::Number v){b.quad(o,m.store(v));};
 if(behavior==100){stage6_boss_final_approach(b,0x48,b.quad(0xa0),b.quad(0xa8),m.precision);if(compare(m.i(b.word(12)),q(0xb0))==0)stage6_boss_final_remove(pool,index,100);const auto y=b.quad(0x48);const auto difference=((y>>52)&2047u)==2047u?y:m.store(m.sub(m.q(y),q(0xa0)));const auto magnitude=stage6_boss_final_absolute(difference);if(real(magnitude)<=real(constant(0x6b25f8)))stage6_boss_final_recolor(pool,index,255,0,0);return;}
 if(behavior==102){if(!remainder(b.word(12),b.word(0x78))){const auto angle=b.quad(0xa8),speed=b.quad(0xa0),y=b.quad(0x48),x=b.quad(0x40);stage6_boss_final_emit(pool,{{9,0,{{255,0,0}},2,255,1,41},x,y,1,0,speed,angle,1,2},player,p,random,precision,math);put(0xa8,m.add(q(0xa8),m.c(0x6d3088)));}return;}
 if(behavior==103){const auto first=b.word(0x78),second=b.word(0x7c);auto a=record(pool,first),z=record(pool,second);put(0x40,m.add(m.mul(m.sub(m.q(z.quad(0x40)),m.q(a.quad(0x40))),q(0xa0)),m.q(a.quad(0x40))));put(0x48,m.add(m.mul(m.sub(m.q(z.quad(0x48)),m.q(a.quad(0x48))),q(0xa0)),m.q(a.quad(0x48))));const auto difference=z.word(0x30)-a.word(0x30);const auto scaled=stage6_boss_final_convert(m.mul(m.i(difference),q(0xa0)));b.word(0x30,scaled+a.word(0x30));return;}
 if(behavior==104){put(0x40,m.add(q(0x40),q(0x50)));if(real(b.quad(0x40))>real(constant(0x6d1bb8))||real(b.quad(0x40))<real(constant(0x6d1b58)))b.word(0,0);return;}
 if(behavior==105){put(0x40,m.add(q(0x40),q(0x50)));put(0x48,m.add(q(0x48),q(0x58)));for(auto& other:pool.bullets){if(other.word(0)!=1||other.word(4)!=11)continue;const auto dx=stage6_boss_final_absolute(m.store(m.sub(q(0x40),m.q(other.quad(0x40)))));if(real(dx)>real(constant(0x6d18e8)))continue;const auto dy=stage6_boss_final_absolute(m.store(m.sub(q(0x48),m.q(other.quad(0x48)))));if(real(dy)>real(constant(0x6d18e8)))continue;const auto speed=m.store(m.add(m.q(p.reals[0]),m.c(0x6d1960)));const auto y=b.quad(0x48),x=b.quad(0x40);stage6_boss_final_emit(pool,{{9,2,{{0,255,0}},2,255,1,41},x,y,1,0,speed,0,0,0},player,p,random,precision,math);stage6_boss_final_remove(pool,index,100);}if(real(b.quad(0x48))>real(constant(0x6d18c8)))b.word(0,0);return;}
 throw std::out_of_range("Stage6 final projectile behavior");
}
}
